import{_ as a,o as r,c as i,ag as t}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"ContainerTraffic — takoform_container_traffic","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/container/container-traffic.md","filePath":"proposals/container/container-traffic.md"}'),o={name:"proposals/container/container-traffic.md"};function s(n,e,c,d,l,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="containertraffic-—-takoform-container-traffic" tabindex="-1">ContainerTraffic — <code>takoform_container_traffic</code> <a class="header-anchor" href="#containertraffic-—-takoform-container-traffic" aria-label="Permalink to &quot;ContainerTraffic — `takoform_container_traffic`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>An operator moves traffic between Container Revisions of one service: canary a new revision at a small share, promote it, or roll back — all by re-weighting, never by mutating a revision.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>deployment</code>. This is the only mutable path for traffic movement.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>revisions</code> lists one to eight entries of <code>containerRevision</code> plus <code>weight</code> in basis points. Weights are positive and must sum to exactly 10000 across entries — the same host-validated rule as the Edge family&#39;s <code>WorkerDeployment</code>, because a JSON schema cannot add weights. Each request is served entirely by one selected revision; a client never observes a blend of two revisions within one request. A revision not listed receives no traffic, and its instance bounds are not in force.</p><p>A Container Service has at most one ContainerTraffic. Attachments are admitted against it and refused when it is absent; deleting it while an attachment lives is refused; and the identity reports Ready only while its traffic resource serves — the family&#39;s aggregate statement, mirroring <a href="./../../spec/decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Revision selection is a single atomic fact per service. Splitting weights across resources would allow interleavings in which the observable sum is temporarily wrong.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Named revision URLs — a tagged revision addressable outside the split — carry a second activation surface and are a separate attachment Form. Header- or cookie-pinned sessions, per-request routing rules, and automated progressive-rollout policies carry different selection semantics and belong to separate Forms.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None; the traffic resource selects revisions, it does not use capabilities.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>A traffic resource referencing a deleted or absent revision must fail closed (<code>resource_not_found</code>, and dependency protection keeps a weighted revision undeletable). Rollback is re-weighting to a previous revision and must not require recreating it. Deleting the traffic resource stops selection but never deletes the service or its revisions, and is refused with <code>dependency_in_use</code> while an attachment lives.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The revision traffic split of a proven serverless container platform, reduced to its portable core: exact basis-point weights over immutable revisions, one active selection per service.</p>',20)])])}const m=a(o,[["render",s]]);export{p as __pageData,m as default};
